export const tutorialLessonRevision = 'desktop-tutorial-capability-coverage-v59';
export interface TutorialRun { version: string; lessonRevision: string; runId: string; state: 'new' | 'shown' | 'finished' | 'skipped' }
export function checkedTutorialRun(value: unknown, applicationVersion: string): TutorialRun {
  if (!value || typeof value !== 'object' || Object.getPrototypeOf(value) !== Object.prototype) throw new Error('Tutoriallauf ist beschädigt.');
  const fields = ['version', 'lessonRevision', 'runId', 'state'];
  const descriptors = Object.getOwnPropertyDescriptors(value);
  if (Reflect.ownKeys(value).length !== fields.length || fields.some(key => !descriptors[key] || !('value' in descriptors[key]))) throw new Error('Tutoriallauf hat ein unbekanntes Format.');
  const row = value as TutorialRun;
  if (row.version !== applicationVersion || typeof row.lessonRevision !== 'string' || !row.lessonRevision || typeof row.runId !== 'string' || !row.runId || !['new', 'shown', 'finished', 'skipped'].includes(row.state)) throw new Error('Tutoriallauf hat ungültige Werte.');
  return { ...row };
}
export const lessons = [
 {id:'extension-installation',title:'Zusatzpakete prüfen und Rechte kontrollieren',text:'Öffne Erweiterungen und wähle eine lokale Paketdatei. Prüfe Name, Version, Pakethash und die angeforderten Rechte; bestätige diese ausdrücklich vor der Installation. Rechte widerrufen beendet die Rechteannahme, Paket entfernen hält den Installationsverlauf. Fehlt eine Schreibantwort, wähle Ergebnis prüfen statt erneut zu installieren. Bei einem beschädigten Auftragsvermerk prüfst du zuerst die aktuelle Installationsliste und kannst dann die Wiederaufnahme zurücksetzen; der ursprüngliche Vermerk bleibt gesichert. Die Paketinstallation bietet derzeit noch keinen zusätzlichen Inhaltseditor.'},
 {id:'session-loot-guidance',title:'Kumulierte Beute im Spielabend ausgleichen',text:'Aktiviere Beuteausgleich für einzelne Roster-Figuren mit bekannten XP. Der Generator liest die Beute-Fortschrittskurve des wirksamen Presets, vergleicht erwartete Gesamtwerte mit dem persönlichen Ledger und berücksichtigt die geplanten neuen XP. Fehlender Wert hält die automatische Berechnung an; freie Planung bleibt mit abgeschaltetem Ausgleich nutzbar. Beutetabelleneinträge werden auf das Budget begrenzt, fehlender Wert als Münzen ergänzt. Die gespeicherte Empfehlung zeigt Inputs, Differenz und Ziel. Du kannst jede Belohnung trotzdem ändern; eigene Änderungen und bereits angenommene/platzierte Inhalte werden nicht automatisch umgeschrieben.'},
 {id:'world-session',title:'Einen Spielabend aus den Weltquellen vorbereiten',text:'Im Spielabendprofil wählst du die Planungsparty, Adventure Day und den Seed. Markiere Orte und Fraktionen; bei aktiver Ortsquellenwahl erzeugt jede Szene ihre Begegnung aus genau diesem Ort. Vorschläge mit eindeutiger Beutetabelle erhalten eigene geplante Beute. Bearbeite Titel, Vorlesetext, GM-Notizen, Wissensverweise und Belohnung vor der Timeline-Übernahme. Begegnung und Beute lassen sich unabhängig neu erzeugen; die anderen Vorschläge und eigenen Texte bleiben erhalten. Ein Ortswechsel braucht eine neue Begegnungsvorschau. Verwerfen und Wiederherstellen betreffen nur den Vorschlag. Belohnungen entstehen erst bei Übernahme als Besuchsvorbereitung und lassen sich dann separat platzieren oder verteilen.'},
 {id:'npc-world',title:'NSCs als bestehende Individuen führen',text:'Unter NSCs und Monstergruppen suchst du einzelne Figuren nach Name, Status, Fraktion und Ort. Lege erzählerische NSCs mit Aussehen, Verhalten und Geschichte an; ein optionaler Kreaturverweis eröffnet dauerhafte HP und Begegnungsteilnahme. Fraktionshaltung plus persönlicher Modifikator ergeben verbündet, neutral oder feindlich. Besiegt sperrt neue Teilnahme, verändert keine HP und beendet keine laufende Maske. Reaktiviere die Figur ausdrücklich. Formulare werden als Arbeitsentwürfe gesichert, auch mit noch ungültigen Zahlen; NPC übernehmen bestätigt die Weltänderung.'},
  {id:'world-sources',title:'Begegnungen aus Ort und Fraktion',text:'Lege Fraktionen und Orte in Welt und Spielabend an. Unter Katalog und Encounter verbindest du die Fraktion mit einer Haupttabelle und ihren Beständen: leer ist unbegrenzt, 0 ist nicht verfügbar. Orte verknüpfen eigene Tabellen und Fraktionen. Wähle den Weltkontext für neue Vorschläge; alle gewählten Filter schneiden ihre Quellen. Vorschläge verbrauchen keinen Bestand. Nach Änderungen an Quellen oder Beständen erzeugst du die Vorschau neu.'},
  { id: 'live-packet', title: 'Mit der Mappe am Spieltisch leiten', text: 'Öffne bei „Spielabend und Besuchsergebnisse“ die Mappe am Spieltisch. Leitungsfunktionen und Mappe bleiben gleichzeitig bedienbar. Blättere durch Besuche oder suche nach Texten. „Besuch übernehmen“ öffnet die vorhandene Vorschau; Vorlesetexte lassen sich ausdrücklich in die laufende Szene kopieren. Die Spielersteuerung bleibt separat; eine bereits freigegebene Szene folgt ihrem bestehenden Anzeigemodus. Die Party-Bearbeitung kannst du bei Bedarf einblenden. Fokus- und Planwechsel binden die Mappe neu.' },
  { id: 'session-progress', title: 'Vom Besuch zum bestätigten Ergebnis', text: 'Am Spieltisch zeigt „Spielabend und Besuchsergebnisse“ die Besuchsfolge eines Plans. „Besuch übernehmen“ öffnet die vorhandene Übernahmevorschau. Halte für den aktuellen übernommenen Besuch Ergebnis und Status fest: abgeschlossen, übersprungen oder wieder offen. Die Chronik und Spielabendmappe behalten die bestätigten Ergebnisse, auch nach Korrektur. XP, Beute und Zeit bestätigst du separat.' },
  { id: 'quick-reference', title: 'Eine Referenz sofort finden und verwenden', text: 'Öffne „Schnellsuche“ in der oberen Leiste oder mit Strg+K. Suche über Weltinhalte und Regeln, Kreaturen, Gegenstände und Begegnungen; Quellen laden getrennt nach. Lies Details, folge benannten Weltverweisen und blättere mit Zurück/Vorwärts durch deinen Verlauf. Anheften verbindet die Referenz mit der angezeigten Fokusgruppe. Vorlesetext kopierst du ausdrücklich in diese laufende Szene. Kreaturen mit Anzahl/Initiative und Begegnungen gehen in die bestehende Vorbereitung am Spieltisch. Spielerfreigabe, Kampfbeginn und Belohnungen bleiben ihre eigenen Aktionen.' },
  { id: 'narrative-journal', title: 'Aufträge und Gerüchte am Tisch führen', text: 'Öffne in der oberen Leiste „Aufträge und Gerüchte“. Suche über Titel, GM- und Vorlesetext oder bestätigte Ergebnisse. Filtere Quests/Gerüchte und offene/geschlossene Einträge. Rechts stehen Texte, Weltverweise und der bestehende narrative Status- und Belohnungseditor. Mitwirkende, Ort und Belohnung werden als Eingabe gesichert. Ein Abschluss verlangt ein manuelles Ergebnis und ausdrücklich gewählte XP-Empfänger oder keine XP. Er gibt die Belohnung nur einmal aus. Die Spielabendmappe zeigt den bestätigten Status und Abschluss gebundener Aufträge.' },
  { id: 'session-review', title: 'Einen Abend gemeinsam vorbereiten', text: 'Erzeuge in der Vorbereitung Spielabend-Vorschläge. Suche über Titel, GM- und Vorlesetext, Orte, Weltverweise und Gegner. Wähle die sichtbaren passenden Szenen aus; ausgeblendete ausgewählte Szenen bleiben im Auswahlzähler sichtbar. Öffne die gemeinsame Prüfung und bestätige die Reihenfolge. Die ausgewählten Besuche werden zusammen hinten an die Timeline angefügt. Öffne anschließend die Spielabendmappe. Einzelbearbeitung und Neugenerierung bleiben möglich; übernommene Vorschläge findest du über den Statusfilter.' },
  { id: 'session-packet', title: 'Den ganzen Spielabend griffbereit haben', text: 'Wähle unter Vorbereitung einen Plan und öffne seine Spielabendmappe. Die Besuchsfolge führt zu Vorlesetext, GM-Notizen, Ortsabschnitten, Weltverweisen, Begegnungen mit Statblocks und Belohnungen. Suche über alle Inhalte. Aktualisieren liest den gespeicherten Stand; als Markdown speichern gibt genau diesen Stand aus. Die Mappe ist für den GM und kann private Inhalte enthalten.' },
  { id: 'live-travel', title: 'Reisen direkt am Spieltisch', text: 'Öffne bei der laufenden Fokusgruppe „Reisekarte am Spieltisch“. Karte und Reisekonsole erscheinen neben der Weltzeit. Wähle Ziele oder Wegpunkte und bestätige Vorschau und Reiseabschnitte hier. Ein Fokuswechsel folgt der neuen Gruppe und entfernt alte Reiseziele. Einklappen und Atlaswechsel behalten den Entwurf derselben Gruppe. Gelände und Kalender bearbeitest du über „Atlas bearbeiten“.' },
  { id: 'map-route', title: 'Eine Reise auf der Karte planen', text: 'Wähle unter Atlas und Reise eine Gruppe und Karte. „Ziel wählen“ oder „Wegpunkte wählen“ macht Kartenklicks zu Reiseeingaben, ohne Gelände zu malen. Nummerierte Stationen lassen sich ordnen und entfernen. Pfeiltasten bewegen den Cursor, Enter wählt ein Hex. Platziere die Gruppe ausdrücklich am Cursor, wenn ihre Kartenposition noch fehlt. Prüfe Route und Zeit und bestätige die Reise. Abschnitte, Pause und Fortsetzen benutzen die gemeinsame Gruppenzeit; nach Ankunft oder Abbruch verschwindet die Route.' },
  { id: 'party-awards', title: 'XP für den ganzen Spielabend abrechnen', text: 'Öffne die Party und „Spielabend-XP abrechnen…“. Wähle Fokusgruppe, aktive Figuren oder einzelne Empfänger. XP-Verdienst und Tagesbelastung haben getrennte Summen und Empfänger. Die Vorschau zeigt XP je Figur und neue Level; bestätige den Grund für eine gemeinsame Buchung. Reservefiguren können XP erhalten. Negative Einzelkorrekturen gehen bis null und leiten auch niedrigere Level automatisch ab. Bestätigter Rastverbrauch und abgeschlossene Rastabschnitte bleiben erhalten.' },
  { id: 'roster-archive', title: 'Figuren archivieren und zurückholen', text: 'Öffne die Party oben und wähle bei einer Figur „Archivieren…“. Bestätige ihren genauen Namen. Party und offene Masken verlieren die Figur; Fortschritt, Beute und Erinnerungen bleiben erhalten. Unter „Archivierte Figuren“ findest du sie nach Namen oder ID wieder. Wiederherstellen setzt sie zunächst inaktiv ins Roster. Wähle ihre Teilnahme danach ausdrücklich.' },
  { id: 'party-topbar', title: 'Party direkt am Tisch verwalten', text: 'Öffne oben die Party (Alt+P). Durchsuche das Roster, lege inaktive Figuren an und ändere ihre Teilnahme ausdrücklich. Profilwerte, Sprachen und passive Werte bleiben optional. Klicke den XP-Balken für Level- und XP-Korrekturen. Gruppenrasten gelten der ausgewählten Gruppe im Fokus und können die gemeinsame Szenenzeit fortschreiben.' },
  { id: 'campaign', title: 'Kampagne als Arbeitsraum', text: 'Lege eine Kampagne an oder übernimm eine v4-Dungeondatei als neue Kampagne. Der Import zeigt seine Grenzen vor der Übernahme; die Quelldatei bleibt unverändert. „Name ändern“ aktualisiert nur die geöffnete Kampagne und behält ihre Identität und Inhalte.' },
  { id: 'campaign-transfer', title: 'Kampagnen vollständig übertragen und löschen', text: 'Unter „Verwalten / Transfer“ exportierst du die geöffnete Kampagne mit Karten, Bildern, lokalen Audiodateien und wiederaufnehmbarem Arbeitsstand oder legst eine unabhängige Kopie an. Vor einem Import vergleichst und entscheidest du Konflikte gemeinsamer Definitionen. Der Papierkorb bleibt wiederherstellbar; dauerhaftes Löschen ist eine getrennte, ausdrücklich bestätigte Aktion.' },
  { id: 'drawing-and-key', title: 'Raum und Key zusammen bearbeiten', text: 'Suche nach Raumname, Nummer oder Keytext. Ziehe Eckpunkte oder gib Meterkoordinaten ein. Der Text bleibt daneben bearbeitbar. Geschosse werden getrennt angezeigt. Gezeichnete Konturen sind noch keine physischen 3D-Räume.' },
  { id: 'saving', title: 'Automatisch speichern und Arbeit wieder aufnehmen', text: 'Gültige Eingaben werden nach kurzer Pause gespeichert. „Gespeichert“ bestätigt den Autorenstand. Ungültige Raumtexte bleiben beim Kampagnenwechsel oder Schließen als Arbeitsentwurf erhalten. Nach Schreibfehlern zuerst den Speicherstatus prüfen. Rückgängig und Wiederholen ändern Kontur und Key gemeinsam.' },
  { id: 'adventuring-day', title: 'Tagesbudget und Level-Prognose immer griffbereit', text: '„Rastbudget“ in der Kopfleiste zeigt den aktuellen Verbrauch der aktiven Party. Öffne den Rechner für Tagesbudget, Rastschwellen und Encounter-Schwierigkeiten. „XP → Tage“ zeigt Etappen und prognostizierte Level. Für Kämpfe kannst du Tagesbelastung und XP-Verdienst getrennt rechnen. „Aktive Party“ nutzt bestätigte XP; eigene Zeilen und „Leeren“ verändern nur die Vorschau. „Party am Tisch öffnen“ führt zu den echten Figuren und Rastaktionen. Große Zeiträume bleiben als zusammengefasste Etappen lesbar.' },
  { id: 'scene-rest', title: 'Rast am laufenden Spieltisch', text: 'Wähle unter einer Partyfigur „Mit der Gruppe rasten“ die beteiligten Figuren. Passe die Dauer an und bestätige eine kurze oder lange Rast. Uhr, Rastbudget und freigegebene Weltfolgen werden gemeinsam fortgeschrieben. Lange Rasten können bekannte Figuren mit positiven HP vollständig heilen; 0 HP, unbekannte HP, temporäre HP und Zustände bleiben erhalten. Ohne Zeitoption korrigierst du nur das Rastbudget. Laufende Kämpfe oder Verfolgungen zuerst abschließen. Die Chronik hält Dauer, Gruppe und HP-Wirkung fest.' },
  { id: 'magic-pools', title: 'Gezielte und abwechslungsreiche Magiebeute', text: 'Öffne in der Spielabendplanung „Magiebeute für diesen Spielabend auswählen“, suche im Katalog und wähle passende Gegenstände. Die Auswahl aktiviert den Seltenheitsausgleich. Vorschläge bleiben in diesem Pool, auch nach Beute-Neugenerierung und Neustart. Fehlende Seltenheiten werden als offene Kontingente gemeldet. Der Pool behält die gewählten Gegenstandsversionen. Ohne eigenen Pool verwendet der Generator den aktiven Katalog. Größere Kontingente werden auf verschiedene Definitionen verteilt; einzelne Vorschläge kannst du weiter manuell bearbeiten.' },
  { id: 'required-opponents', title: 'Einen Gegner verbindlich einplanen', text: 'Öffne im Encounter-Generator oder Spielabend „Verbindliche NPC-Gegner“, suche einen aktiven feindlichen NPC mit Statblock und wähle ihn aus. Der Generator rechnet seinen XP-Beitrag vor der Ergänzung anderer Gegner ein. Monsterfilter und Tabellen gelten für die Ergänzung. Jeder gesetzte NPC behält seine Identität und einen eigenen Initiativeplatz. Ein Spielabend verteilt die gesetzten Gegner einmal auf ihre gewählten Orte; ohne Orte auf unterschiedliche Szenen. Vorschau, Übernahme und einzelne Neugenerierung bleiben getrennte Schritte.' },
  { id: 'world-notes', title: 'Weltwissen wiederfinden', text: 'Unter „Welt und Spielabend“ legst du NSCs, Fraktionen, Quests und Gerüchte an. Vorlesetext und GM-Notizen sind getrennte Felder. Die Suche findet auch GM-Notizen. Der Papierkorb hält Einträge für eine Wiederherstellung vor.' },
  { id: 'preparation-recovery', title: 'Offene Vorbereitung sicher wiederaufnehmen', text: 'Gültige Änderungen an Weltwissen, Orten und dem manuellen Plan werden nach kurzer Pause gespeichert. Ein ungeklärter Schreibausgang sperrt weitere Änderungen: „Speicherstatus der Vorbereitung prüfen“ klärt zuerst den ursprünglichen Auftrag und bewahrt den offenen Entwurf. „Entwurf verwerfen und aktualisieren“ verwirft nur den betroffenen Arbeitsstand. Wiederaufgenommene Entwürfe sind noch kein bestätigter Autorenstand. Spielabendprofil und Besuchsdetails besitzen ihren eigenen Speicherweg und müssen bei ungültigen Eingaben vor dem Wechsel abgeschlossen werden.' },
  { id: 'manual-planning', title: 'Eine Szenenfolge vorbereiten', text: 'Lege einen Plan an, füge Szenen hinzu und verschiebe sie in der Reihenfolge. Notizen und Reihenfolge bleiben nach Neustart erhalten. Ein Plan braucht weder Party noch Ort. Er erzeugt noch keine LiveSession.' },
  { id: 'session-generation', title: 'Spielabendvorschläge mit bindenden Vorgaben erzeugen', text: 'Öffne im manuellen Plan „Planungsparty und Spielabend-Vorschläge“. Die erwartete Party und der Adventure-Day-Anteil gelten nur für diese Planung. Ausgewählte Orte, Weltinhalte und Encounter-Tabellen sind bindend; ein nicht erfüllbarer Auftrag bleibt mit Erklärung gesperrt. Vorschauen sind gespeichert und reproduzierbar. Du kannst einzelne Ergebnisse annehmen oder neu erzeugen, ohne andere angenommene oder manuelle Inhalte zu ersetzen.' },
  { id: 'locations', title: 'Orte, Szenen und Karten verbinden', text: 'Unter „Orte“ legst du einen Ort oder eine Stadt mit eigenen Abschnitten an. Verknüpfe eine vorhandene Dungeonzeichnung und wähle denselben Ort in einer Szene. „Ort öffnen“ führt zu den Notizen, „Karte öffnen“ zur Zeichnung. Ein Ort darf auch unverortet und ohne Karte bestehen. Die Zuordnung erzeugt keine Reise oder LiveSession.' },
  { id: 'relationships', title: 'Beziehungen verfolgen', text: 'Verknüpfe einen Wissenseintrag mit einem NSC, einer Fraktion, Quest oder einem Gerücht und benenne die Beziehung. Die Schaltfläche öffnet das Ziel; eingehende Verweise führen zurück zur Quelle. Ein Ziel im Papierkorb bleibt als solches sichtbar, statt den Verweis zu löschen.' },
  { id: 'live-party', title: 'Party und laufender Spielabend', text: 'Unter „Party und Leiten“ legst du Figuren an und aktivierst die heutige Party. Profilwerte bleiben optional. „Sitzung starten / weiterführen“ öffnet ausdrücklich die laufende Scene. Übernimm einen vorbereiteten Besuch nach Vorschau und bearbeite seine Inhalte während des Spiels weiter. Vorbereitung und Herkunft bleiben erhalten; der nächste Besuch benutzt dieselbe Scene und Uhr. Nach Neustart führt dieselbe Schaltfläche weiter.' },
  { id: 'live-recovery', title: 'Offene Live-Eingaben sicher klären', text: 'Scene- und Figurenänderungen werden nach kurzer Pause gespeichert; „Eingabe abschließen“ versucht offene gültige Werte sofort zu übernehmen. Bleibt der Ausgang eines Schreibauftrags unklar, sperrt die Sitzung weitere Änderungen. „Speicherstatus der Sitzung prüfen“ klärt genau diesen Auftrag und lässt einen konkurrierenden Entwurf offen. „Entwurf verwerfen und aktualisieren“ lädt ausdrücklich den gespeicherten Sitzungsstand und verwirft offene Scene- und Figureneingaben.' },
  { id: 'scene-desk', title: 'Kampagnenwissen an der Scene bearbeiten', text: 'Der Szenentisch folgt der fokussierten Gruppe. Suche Weltwissen, Gegenstände, Kreaturen oder Encountervorlagen und hefte passende Treffer an diese Scene. Weltwissen und Orte kannst du direkt anlegen oder bearbeiten; diese Inhalte bleiben kampagnenweit gemeinsam, während die Auswahl am Szenentisch gruppenspezifisch ist. Vor einem Inhaltswechsel wird eine gültige Eingabe gespeichert; ein wiederaufgenommener Entwurf wird sichtbar gemeldet. Kreaturen und Encounter gehen erst über ihre eigene Schaltfläche in eine Kampfmaske.' },
  { id: 'plan-replacement', title: 'Einen neuen Abend aus vorhandener Vorbereitung bauen', text: 'Plan ersetzen / wiederverwenden öffnet eine Vorschau. Wähle eine leere Timeline oder einen vorhandenen Plan und übernimm auf Wunsch dessen Planungsparty und Adventure Day. Besuche und noch nicht angenommene Gruppen werden als neue Vorbereitung kopiert. Platzierte Gruppen und Schätze behalten ihre Identität; bereits vergebene Besuchsbelohnungen bleiben abgeschlossen. Der bisherige Plan verliert seine Timeline und Vorschläge, während laufende Scenes ihre übernommenen Inhalte behalten. Timeline leeren verwendet denselben Ablauf ohne Vorlage und behält den Plannamen und die Planungsparty.' },
  { id: 'multiple-encounters', title: 'Mehrere Begegnungen in derselben Scene', text: 'Weitere Begegnung bleibt auch während eines offenen Kampfes verfügbar. Wähle die gewünschte Begegnung im Auswahlfeld; jede führt ihre eigene Initiative, Runden und ihr Ergebnis. Eine Figur darf an mehreren Begegnungen teilnehmen. HP und Zustände werden zwischen diesen Masken geteilt. Änderungen aus einer anderen Maske machen ältere Rückgängig-Schritte ungültig; ein Hinweis erklärt das. Beim Verschieben oder Deaktivieren eines PCs wird er aus allen offenen Begegnungen und Verfolgungen entfernt. Sein HP-Stand und die bisherigen Masken bleiben erhalten.' },
  { id: 'magic-guidance', title: 'Magiebeute für den Spielabend', text: 'Der zusätzliche magische Beuteausgleich vergleicht bestätigte XP mit bereits erhaltenen Gegenständen nach Seltenheit. Käufe und Weitergaben zählen nicht erneut. Münzbeute und magische Kontingente werden getrennt berechnet; unbekannte Magiepreise blockieren diesen Modus nicht. Neue Kontingente werden einmal für den ganzen Abend kaufmännisch gerundet und auf Szenen verteilt. Der Katalog ergänzt konkrete Gegenstände, fehlende Seltenheiten bleiben als offen sichtbar. Unter Inhalte und Belohnung bearbeiten ergänzt du Kataloggegenstände mit ihrer Definition oder bearbeitest ausdrücklich einen eigenen freien Eintrag. Beute neu erzeugen hält die gespeicherten Ziele auch ohne Beutetabelle ein. Vorschau und Bearbeitung vergeben nichts automatisch.' },
  { id: 'mixed-opponents', title: 'Benannte Gegner mit einer Eskorte', text: 'Der gemischte Modus bevorzugt vorhandene feindliche NPCs, wenn ihr Kreaturtyp in der gewählten Begegnung vorkommt. Die übrige Menge entsteht aus den Tabellen. Benannte Gegner verbrauchen Plätze derselben Bestandsgrenze; sie werden nicht zusätzlich auf die Menge aufgeschlagen. Ort, Fraktion und Katalogfilter gelten weiter. Vorschläge zeigen die Namen plus die noch unbenannte Menge. Beim Platzieren oder Leiten entstehen neue Weltfiguren nur für diese übrige Menge. Benannte Gegner behalten ihren aktuellen Zustand. Nur NPCs bleibt ein eigener Modus ohne neue Tabellengegner.' },
  { id: 'npc-generation', title: 'Benannte Gegner für den Spielabend', text: 'In Encounter- und Spielabend-Vorschauen wählt Vorhandene feindliche NPCs die tatsächlichen Weltfiguren. Sie benötigen einen Statblock, positive HP und eine feindliche Haltung. Ort, Fraktion und Katalogfilter begrenzen die Auswahl; optionale Tabellen begrenzen die Kreaturtypen. Jeder NPC erscheint pro Begegnung höchstens einmal. Die Vorschau verändert weder Standort noch HP. Beim Leiten werden dieselben Figuren mit ihrem aktuellen Zustand geöffnet, keine Kopien. Figuren an einem anderen Ort müssen zuvor ausdrücklich umplatziert werden. Der Katalogmodus bleibt für neue Monstergruppen verfügbar.' },
  { id: 'prepared-groups', title: 'Monstergruppen dauerhaft vorbereiten', text: 'Unter Monstergruppen legst du eine leere Gruppe oder eine Kopie einer Encounter-Vorlage an. Ergänze Figuren aus dem Katalog, bearbeite einzelne Namen, HP, Zustände und Notizen und wähle einen Standort. Gruppenangaben übernehmen bestätigt den Weltinhalt unabhängig vom Spielabendplan. Offene Eingaben bleiben als Entwurf erhalten. Aus Gruppe entfernen erhält die NPC-Figur und ihren Verlauf. Am aktuellen Szenenort wählst du die gewünschten Figuren vor Begegnung vorbereiten; das startet noch keine Kampfrunden.' },
  { id: 'treasury', title: 'Schätze bearbeiten und verschieben', text: 'Unter Schätze bearbeitest du den unverteilten Rest, setzt einen Standort und ergänzt Kataloggegenstände. Bereits vergebene Mengen bleiben im persönlichen Ledger erhalten. Schatzangaben übernehmen bestätigt gültige Eingaben; erst danach kannst du Teilmengen verschieben oder vergeben. Ein angefangener Entwurf bleibt nach Neustart verfügbar. Am aktuellen Szenenort öffnet Schatz öffnen und zuweisen den platzierten Fund, ohne Beute automatisch zu vergeben.' },
  { id: 'groups', title: 'Partygruppen führen', text: '„Gruppe im Fokus“ wählt die Gruppe, deren Inhalte und Uhr du bearbeitest. Unter „Party aufteilen / zusammenführen“ wählst du Figuren und eine neue oder bestehende Zielgruppe. Eine neue Gruppe beginnt am Ort und Zeitpunkt der Ausgangsgruppe und besitzt danach eine eigene Uhr. Eine bestehende Zielgruppe behält ihre Inhalte und Uhr; prüfe den angezeigten Zeitpunkt vor der Übernahme. Leere frühere Gruppen findest du im Archiv zum Nachlesen.' },
  { id: 'relative-time', title: 'Zeit einer Gruppe fortsetzen', text: 'Unter „Zeit verstreichen lassen“ wählst du eine positive ganze Dauer in Sekunden, Minuten, Stunden oder Tagen. „Danach“ zeigt den Zeitpunkt vor der Bestätigung. Die Uhr der gewählten Gruppe wird gespeichert, andere Gruppenuhren bleiben unabhängig. Die Anzeige zählt seit Kampagnenbeginn; Fantasykalender, Reise und automatische Weltfolgen werden erst mit ihren jeweiligen Funktionen verbunden.' },
  { id: 'encounter-catalog', title: 'Begegnungen vorbereiten und leiten', text: 'Unter „Katalog und Encounter“ suchst du Kreaturen, liest ihren Statblock und stellst wiederverwendbare Begegnungsvorlagen zusammen. Planungsparty und Schwierigkeit gehören zur Vorbereitung. Erst die ausdrückliche Vorbereitung für die aktuelle Gruppe öffnet die Begegnung im Livebereich; Initiative, Trefferpunkte, Zustände und Abschluss sind dort bedienbar.' },
  { id: 'combat-rewards', title: 'Kampf, XP und Beute gemeinsam abschließen', text: 'Beim Kampfabschluss bestätigst du Ergebnis, XP-Pool, Empfänger und optionale Beute zusammen. Die Vorschau zeigt den aufgerundeten Anteil je ausgewählter Figur; „Keine XP“ bleibt eine ausdrückliche Wahl. Vorbereitete oder platzierte Beute wird dadurch nicht automatisch vergeben: Für jeden Posten wählst du den Empfänger. Spätere XP- und Beutekorrekturen ändern den aktuellen Stand und behalten den erklärenden Verlauf.' },
  { id: 'character-health', title: 'HP, Zustände und Todesrettungswürfe führen', text: 'Bei der ausgewählten Figur speicherst du aktuelle, maximale und temporäre HP, Zustände und Konzentration zusammen; ungespeicherte Eingaben bleiben als Entwurf stehen und sperren die schnellen Schaden-/Heilknöpfe. Bei 0 HP erscheinen Todesrettungswürfe mit Erfolgen, Fehlschlägen, natürlicher 1 und 20 sowie ausdrücklichem Stabilisieren, Tod und Zurücksetzen. Während eines Kampfes führst du diese Werte im Kampftracker; sein bestätigter Stand geht nach dem Abschluss zurück an die Figur.' },
  { id: 'character-progression', title: 'XP und Rastbudget nachvollziehbar ändern', text: 'Manuelle XP kannst du hinzufügen, abziehen oder auf einen Gesamtstand setzen und mit Grund sowie optionalem früherem Eintrag als Korrektur speichern. Level, nächste Schwelle und Rastbudget folgen dem aktuellen XP-Stand. Kurze und lange Rasten bestätigst du für die ausgewählten Figuren der fokussierten Gruppe; sie ändern das Belastungsbudget und auf Wunsch die gemeinsame Gruppenzeit. Bei einer langen Rast kann die ausdrückliche HP-Erholung bekannte Figuren mit positiven HP vollständig heilen; 0 HP, unbekannte HP, temporäre HP und Zustände bleiben erhalten. Der Fortschritts- und Beuteverlauf hält die bestätigten Änderungen fest.' },
  { id: 'personal-loot', title: 'Persönliche Beute mit Herkunft weiterführen', text: 'Weise unverteilte Beute ausdrücklich einer aktiven Figur zu oder erfasse einen persönlichen Eintrag als Belohnung, Kauf oder manuelle Herkunft. Suche und Filter zeigen erhaltene, verkaufte und weitergegebene Einträge; Verkäufe, Weitergaben und Mengenkorrekturen bewahren den früheren Stand im Verlauf. Mengenstapel kannst du teilen, passende Stapel zusammenführen oder an eine andere Figur übertragen. Interne Weitergaben und Käufe zählen nicht als neue erhaltene Kampagnenbeute; Münzen werden nicht automatisch gebucht.' },
  { id: 'chase', title: 'Eine Verfolgung über Runden führen', text: 'Im Livebereich startest du für die fokussierte Gruppe eine Verfolgung. Trage Verfolger und Flüchtende mit Tempo ein. Pro Runde hältst du relative Distanz, Erschöpfung und eine Komplikation fest. Der Stand bleibt nach Neustart erhalten; der ausdrückliche Abschluss schreibt das Ergebnis in die Kampagnenchronik.' },
  { id: 'chronicle', title: 'Momente festhalten und Kampagnenfolgen nachlesen', text: 'Unter „Party und Leiten“ hältst du einen Moment für die fokussierte Gruppe fest und kannst daraus zugleich eine offene Quest oder ein Gerücht vorbereiten. Ein Fokuswechsel bewahrt den Entwurf bei seiner Gruppe; neuere Eingaben werden nach einer langsamen Speicherantwort nicht gelöscht. Quest- und Gerüchtstreffer der Live-Suche zeigen ihren aktuellen Stand und öffnen ihre Verwaltung in der Vorbereitung. Die Kampagnenchronik ordnet bestätigte Kämpfe, Resultate, Belohnungen, Reisen, Partyänderungen und Weltfolgen zeitlich ein, lässt sie filtern und als Markdown ausgeben. Sie ersetzt kein vollständiges Kampagnenpaket.' },
  { id: 'session-recap', title: 'Einen Spielabend beginnen und mit Rückblick beenden', text: '„Spielabend beginnen“ setzt eine dauerhafte Markierung in der Kampagnenchronik. Danach zeigt der Rückblick die bestätigten Ereignisse seit diesem Beginn; bei mehr als zwölf Einträgen findest du den vollständigen Abschnitt in der Chronik. „Spielabend beenden“ speichert Abschlussnotiz und Übergabe für den nächsten Abend. „Nächsten Abend vorbereiten“ vergleicht fortbestehende Gruppen, Weltlage, Besuche, Aufträge, Masken und Beute; erst „Spielabend hier beginnen“ setzt den neuen Marker. Die Markierung folgt der ganzen Kampagne und teilt keine Partygruppen oder deren Uhren zusammen.' },
  { id: 'session-content', title: 'Spielabendinhalte und Vorschläge verwenden', text: 'Ein vorbereiteter Besuch kann Vorlesetext, Weltverweise, NPC-Gruppen und Beute enthalten. Gruppen und Schätze werden ausdrücklich am Ort platziert. Generierte Vorschläge bleiben Vorschläge, bis du einzelne Besuche annimmst. Beim Spielen übernimmt die Vorschau den ausgewählten Besuch in die fortbestehende Gruppe; platzierte NPCs behalten ihre Trefferpunkte.' },
  { id: 'item-definitions', title: 'Gegenstände als Definitionen pflegen', text: 'Suche und filtere den Gegenstandskatalog oder lege eine eigene Definition mit Beschreibung, Eigenschaften und optionalem Richtwert an. SRD-5.1-Einträge sind schreibgeschützt; „Eigene Kopie anlegen“ erzeugt eine bearbeitbare Definition. Papierkorb und spätere Änderungen betreffen ihre aktuelle Verwendung. Bereits aufgezeichnete Vergabe- und Handelswerte bleiben im Verlauf erhalten. Von einer Definition aus kannst du persönliche Beute, unverteilte Beute oder einen Shopbestand ausdrücklich anlegen.' },
  { id: 'items-trade', title: 'Shops, Bestand und Handel führen', text: 'Lege einen Shop für einen vorhandenen Ort oder NPC an und bestimme Bestand sowie Verkaufs- und Ankaufspreise. Bei einem Gegenstand ohne Richtwert bestätigst du die Shoppreise ausdrücklich. Käufe ändern Shopbestand und persönlichen Ledger zusammen; Verkäufe halten Menge und tatsächlichen Erlös fest. Münzen buchst du weiterhin am Charakterbogen. Einzelstücke werden nicht automatisch aufgefüllt. Andere Auffüllregeln folgen bestätigter Spielzeit; die Handels- und Auffüllhistorie zeigt ihre Wirkung.' },
  { id: 'atlas-hex', title: 'Hexkarten und Orte bearbeiten', text: 'Unter „Atlas und Reise“ erstellst, kopierst oder importierst du eine eigenständige Hexkarte. Gelände, Höhen, Straßen, Flüsse und Klima sind einzeln oder mit dem Pinsel editierbar; Kartenexport und -import verwenden die sichtbaren JSON-Daten. Markiere bestehende Orte auf der Karte und wechsle den Maßstab mit Mausrad oder Zoomschaltflächen. „Für diese Gruppe aufdecken“ schreibt das Hex in die dauerhafte Kenntnis ihrer aktuellen Figuren. „Gruppe hier platzieren“ setzt die ausdrücklich gewählte Gruppe ohne Reisezeit.' },
  { id: 'travel-checkpoints', title: 'Eine Reise wirklich fortsetzen', text: 'Wähle Gruppe und Ziel und lass Route, Dauer und Ankunft anzeigen. Gelände, Tempo und Wetter wirken auf die Vorschau; eine vorgegebene Enddauer gewinnt. Die Annahme bewegt noch niemanden. Bestätige den nächsten Abschnitt oder gehe bis zur nächsten Grenze weiter. Ein markierter Hinweis hält für deine Entscheidung an. Nach Neustart bleibt die angenommene Reise verfügbar.' },
  { id: 'calendar-events', title: 'Kalender und örtliche Ereignisse', text: 'Bearbeite Monate, Tageslänge, Wochentage und erstes Jahr im Atlasbereich. Ein anderer Kalender deutet dieselben aufgezeichneten Zeitpunkte neu. Ereignisse können einmalig oder wiederkehrend und an einen Ort gebunden sein. Im Livebereich erscheinen die Ereignisse, die zur Zeit und zum Ort dieser Gruppe passen; narrative Folgen entscheidest du selbst.' },
  { id: 'weather-control', title: 'Wetter entwickeln und ausdrücklich vorgeben', text: 'Das Kartenklima und regionale Hexklimate liefern saisonales Wetter. Eigene Wettergebiete besitzen Zentrum, Größe, Bewegung, Dauer und Hinweise und können pausiert oder beendet werden. Wetter folgt bestätigter Gruppenzeit. Die Liveanzeige nennt Sicht und Reiseeffekte. Ein GM-Wetteroverride bleibt für diese Gruppe bestehen, bis du „Wetterautomatik freigeben“ wählst.' },
  { id: 'dungeon-tools', title: 'Grundriss, Geschosse und gebundene Details zeichnen', text: 'Karte und Keys enthält direkte Zeichenwerkzeuge. Rechteck oder Polygon bestätigen, Höhlen mit Pinsel anfügen oder ausradieren und Wände, Türen, Licht, Objekte, Flächen und Text setzen. Türen binden an die gewählte Raumkontur; Raumtransformationen bewegen gebundene Details gemeinsam. Alle Autorenänderungen nutzen denselben Undo-Cursor. Raum-Keys behalten ihre IDs, Archiv und Geschossgeometrie-Kopien erhalten Originaltexte. Deckenhöhe und Schnittansicht zeigen die metrischen Höhen. Fallen-Charges verbrauchst du ausdrücklich; Reset benutzt bestätigte Gruppenzeit und wird durch Autoren-Undo nicht zurückgespult.' },
  { id: 'dungeon-structure', title: 'Dungeonstruktur, Inhalte und 3D-Verbindungen vertiefen', text: 'Die Schaltflächen über der Karte öffnen getrennte Werkzeuge für 3D-Volumen, Triggerfelder, platzierte Inhalte, Graphentwurf, Dungeon-Keys und Passagen. Graphänderungen bleiben in einer geschützten Arbeitskopie, bis du die Rastervorschau ausdrücklich übernimmst. Volumen und Paths verwenden Meter- und 5-Fuß-Höhen; bewegte Endpunkte schreiben bestehende Volumen nicht stillschweigend um. Inhalte und Trigger behalten ihre Besitzer und Anker oder werden sichtbar zur Neuzuordnung erhalten.' },
  { id: 'live-rules', title: 'Regelreferenzen und Proben bei der Gruppe halten', text: 'Im Livebereich suchst du Regelnotizen und heftest einen eingefrorenen Stand an die fokussierte Gruppe. Eine geänderte oder fehlende Quelle überschreibt ihn nicht; Aktualisieren bleibt ausdrücklich. Schnelle d20-Proben und Statblockformeln werden mit Wurfart, Modifikator, optionalem SG oder RK und Scene-Zeit bei dieser Gruppe protokolliert. Ein unbekannter SG bewahrt ein offenes Ergebnis statt Erfolg oder Fehlschlag zu erfinden.' },
  { id: 'npc-autonomy', title: 'NPCs mit begrenztem Verhalten beauftragen', text: 'Unter NPC-Verhalten aktivierst du bestehende Figuren oder Gruppen. Bedürfnisse, Rollen und Prioritäten wählen gültige Jobangebote. Lege erreichbare Ortswege und exklusive Angebote an. Nur bestätigte Gruppen-/Reisezeit zählt; ausstehende Intervalle behalten ihre damaligen Regeln. Bestätigte Zeit nachholen arbeitet in kurzen atomaren Schritten. Partygefahr hält vor einer Wirkung an; der Verlauf erklärt Auswahl, Ausschlüsse und GM-Entscheidungen.' },
  { id: 'player-cues', title: 'Inhalte am Spieltisch ausdrücklich freigeben', text: 'Die Schaltflächen neben der laufenden Scene zeigen das aktuelle Ortsbild, ein gewähltes NPC-Porträt oder ein spontanes Bild-Handout für die geprüfte Gruppe. Vorlesetext und GM-Notizen bleiben im GM-Arbeitsraum. Beim ersten Bild wählst du eine lokale Datei; danach reicht die ausdrückliche Freigabe. „Live-Automatik“ kehrt zur fokussierten Karte oder zum aktuellen Ortsbild zurück. Ein inzwischen geänderter Gruppenfokus stoppt die Freigabe. „Anzeige leeren“ blendet nur das Fenster aus; GM-Notizen und Charakterkenntnis werden nicht mitgesendet oder verändert.' },
  { id: 'player-display', title: 'Kenntnis und aktuelle Sicht der Gruppe trennen', text: 'Spieleranzeige öffnet eine schreibgeschützte Vorschau und ein Fenster auf dem gewählten Bildschirm. Entdecken und Vergessen ändern dauerhafte Karten- und Ortskenntnis nur für die ausgewählten Figuren; Sichtweite, Dunkelsicht und Augenhöhe bestimmen dagegen die momentane Sicht. Die Ausgabe vereinigt ausschließlich die fokussierte Gruppe und filtert sie zusätzlich mit Licht, Wetter, Höhe und Sichtmasken. Öffentliche Beschriftungen bleiben von GM-Texten getrennt. Ausblenden, Schließen und ein Bildoverride verändern weder Kenntnis noch aktuelle Weltwahrheit.' },
  { id: 'extensions', title: 'Lokale Erweiterungspakete kontrollieren', text: 'Unter „Erweiterungen“ prüfst du ein lokales Paket und bestätigst genau die angezeigten Rechte. Widerrufen entfernt die Rechte; Entfernen löscht zusätzlich den gespeicherten Paketcode, bewahrt aber kampagneneigene Zusatzdaten. Ein unklarer früherer Auftrag sperrt neue Änderungen, bis der aktuelle Installationsstand vollständig gelesen und der beschädigte Vermerk ausdrücklich gesichert wurde. Erweiterungscode wird in diesem Produktstand noch nicht ausgeführt.' },
  { id: 'city-infill', title: 'Vom Straßenzug zum editierbaren Stadtplan', text: 'Lege zuerst einen Kampagnenort an und öffne Städte. Zeichne Straßen, Viertelflächen und Hindernisse in Metern. Dichte, Hausgröße, Abstand und Seed erzeugen eine Vorschau; erst Bebauung übernehmen speichert Häuser. Benenne oder verändere einzelne Häuser: sie bleiben bei Regeneration geschützt. Rückgängig/Wiederholen, Papier-/Dachfarben und SVG-Ausgabe verwenden den gespeicherten Stadtstand.' },
  { id: 'npc-dossier', title: 'NSCs am Spieltisch führen', text: 'NSCs am Spieltisch listet die Figuren am Gruppenort oder aus der ganzen Kampagne. Das Dossier verbindet Aussehen, Verhalten, Vorlesetext, Geschichte, Fraktion, eingehende und ausgehende Beziehungen, Gruppen, HP und bestätigtes NPC-Verhalten. Statblocks laden erst beim Öffnen. Gespräch festhalten öffnet den bestehenden Profilentwurf mit Datum und Gruppe; die Eingabe wird als Entwurf gesichert und erst mit NPC übernehmen bestätigt. Vorlesetext und Begegnung nutzen ihre bestehenden Live-Besitzer. Ein Dossier aktiviert keine Autonomie und startet keinen Kampf.' },
  { id: 'travel-camp', title: 'Unterwegs warten, rasten und den Restweg fortsetzen', text: 'Die Reisevorschau zeigt Ankunft, Gelände, Wetter und GM-Halte je Abschnitt sowie Fristen an Reiseorten. Am Live-Spieltisch öffnet Pausieren / warten den Zeitdialog und Pausieren / rasten die vorhandene Party-Rast. Keine Bewegung erfolgt dabei automatisch. Nach Zeit-, Wetter-, Karten- oder Gruppenänderungen Restweg neu bewerten: Ziel und verbliebene Hexfolge bleiben erhalten, die Vorschau berechnet neue Zeiten. Erst Restreise ausdrücklich annehmen ersetzt den alten Plan; danach Abschnitte bestätigen. Bereits gereiste Abschnitte und der frühere Plan bleiben im Verlauf.' },
  { id: 'calendar-time', title: 'Bis Datum oder Ereignis warten', text: 'Am Spieltisch öffnet Warten bis Datum / Ereignis einen Zeitdialog. Wähle Dauer, Datum, Ereignisbeginn/-ende oder nächsten Tagesbeginn. Die Vorschau zeigt das genaue Ziel im Kampagnenkalender und Kalenderereignisse unterwegs. Erst Zeit ausdrücklich verstreichen lassen schreibt die vorhandene Gruppen-Clock fort und verarbeitet ihre Zeitfolgen. Auch Tage in der normalen Zeitsteuerung folgen jetzt der Kampagnen-Tageslänge. Frühere Zeitbelege behalten ihre damalige Bedeutung. Bei geänderter Uhr, Kalenderdefinition oder Ereignisrevision eine neue Vorschau prüfen; Rastwirkungen weiterhin im Rastbereich bestätigen.' },
  { id: 'campaign-agenda', title: 'Fristen an der Gruppenzeit planen', text: 'Kalender / Fristen öffnet die Agenda zur bestätigten Zeit der fokussierten Gruppe. Suche über Ereignisnamen und GM-Notizen; begrenze Zeitraum und Ort. Lege Fristen in Minuten, Stunden, Kampagnentagen oder Wochen an oder wähle Jahr, Monat, Tag und Uhrzeit. Wiederkehrende Ereignisse zeigen ihre aktuelle oder nächste Ausführung. Prüfe die Datums- und Wiederholungsvorschau und speichere ausdrücklich. Ereignisse einschließlich Papierkorb öffnen sich auch aus den Kalenderregeln. Bestehende Orte lassen sich zuordnen, Ereignisse ausdrücklich wiederherstellen. Der bestehende Kalender bleibt die einzige Quelle; Planung verändert keine Gruppenzeit. Offene Angaben bleiben bis Speichern oder ausdrücklichem Verwerfen erhalten.' },
  { id: 'dungeon-binder', title: 'Raum-Keys beim Leiten lesen', text: 'Öffne den Dungeon-Binder auf der Karte oder unter Dungeon leiten. Suche über alle Räume, Vorlagentexte, Geheimnisse und Rauminhalte; filtere Dungeon oder Geschoss. Lies GM-Blöcke, Suchhinweise, wirksame Attribute, verbundene Räume und Fallenstände. Die öffentliche Textvorschau nutzt das bestätigte Gruppenwissen; die Spieleranzeige behält ihre tatsächliche Wahrnehmung. Als Reiseziel wählen öffnet den bestehenden Leitablauf. Erst dessen Bestätigung bewegt die Gruppe. Lesen oder Weiterblättern verändert keine Zeit, Entdeckung, Charges oder Beute.' },
  { id: 'scene-visits', title: 'Übernommene Besuche bleiben bei der Gruppe', text: 'Öffne am Spieltisch „Übernommene Besuche ansehen“. Der Besuchsbinder hält Titel, GM-Notizen, Vorlesetext und Notizbindungen einer Übernahme fest, auch wenn du danach den Plan ersetzt oder den Besuch aus der Timeline entfernst. Ergebnisse und übernommene Begegnungsgruppen bleiben erreichbar. Weltverweise und NPC-Werte zeigen den aktuellen Weltstand. Du kannst einen festgehaltenen Vorlesetext ausdrücklich in die laufende Gruppe kopieren. Ältere Übernahmen ohne Snapshot sind als solche markiert; fehlende frühere Inhalte werden nicht erfunden.' },
  { id: 'treasure-distribution', title: 'Einen Schatz gemeinsam verteilen', text: 'Öffne im Schatzbereich oder am Spieltisch „Beute verteilen“. Wähle den Schatz und die aktiven Empfänger. Die Gleichverteilung verteilt ganze Einheiten; Reste bleiben im Schatz. Korrigiere einzelne Mengen oder weise einen besonderen Posten vollständig einer Figur zu. Prüfe die Gesamtverteilung und bestätige sie zusammen. Herkunft, Gegenstandsdefinitionen und Werte werden im persönlichen Lootledger bewahrt. Bereits vergebene Mengen stehen nicht erneut zur Auswahl; XP und Käufe gehören zu ihren eigenen Abläufen.' },
  { id: 'live-generation', title: 'Begegnungen direkt für die laufende Gruppe erzeugen', text: 'Öffne am Spieltisch „Begegnung erzeugen“. Die aktuelle fokussierte Gruppe mit ihren bekannten XP/Leveln ersetzt eine gesonderte Planungsparty. Wähle Schwierigkeit, Tabellen, Ortsquellen, Fraktionen oder verbindliche NPCs und erzeuge bis zu fünf gespeicherte Vorschläge. Vergleiche XP und Statblocks. „Für diese Gruppe vorbereiten“ übernimmt einen Vorschlag samt Vorlage in eine neue Kampfmaske. Die bisherigen Masken bleiben erhalten; Start, Initiative, Abschluss und Belohnungen bleiben ausdrückliche Schritte. Gespeicherte Vorschauen findest du nach Neustart wieder. Veränderte Gruppe, Orte oder Quellen erfordern eine neue Vorschau.' },
  { id: 'session-reuse', title: 'Vorbereitete Szenen für den nächsten Abend nutzen', text: 'Öffne im Plan „Szenen wiederverwenden“. Wähle einen Quellplan, durchsuche seine Besuche und stelle die gewünschte Reihenfolge zusammen. Erstelle einen eigenen Abend samt Planungsparty oder hänge die Auswahl an einen bestehenden Plan an. Vorlesetexte, GM-Notizen, Weltverweise und offene Belohnungen werden übernommen. Noch nicht platzierte Begegnungen werden unabhängig vorbereitet; platzierte Gruppen bleiben dieselben NPCs. Gebuchte Belohnungen bleiben gebucht. Laufende Gruppen und Besuchsergebnisse gehören weiterhin zum tatsächlich gespielten Abend.' },
  { id: 'live-soundboard', title: 'Den Spielabend direkt am Tisch vertonen', text: 'Öffne in der laufenden Szene das Soundboard oder springe mit „Soundboard“ im kleinen Player direkt dorthin. Merke Titel und Umgebungsgeräusche aus der Bibliothek als Kampagnenfavoriten. Starte Musik, füge Sounds hinzu oder stelle mehrere ausgewählte Titel gemeinsam in die Warteschlange. Pause, Stopp und Automatikfreigabe verwenden denselben Player wie der Musikbereich. Favoriten und Soundwahl bleiben gespeichert; nach Neustart gibt erst ein ausdrücklicher Start wieder Ton frei. Der Musikbereich bleibt für Beschreibungen, Medienimport, Lautstärke und Szenenregler erreichbar.' },
  { id: 'music-library', title: 'Lokale Musik und Umgebungs-Sounds', text: 'Unter „Musik und Ambience“ fügst du lokale Audiodateien hinzu und beschreibst sie mit Intensität, Stimmung, Vibes, Genres und Notizen. Eigene Stimmungsachsen stehen auch als Szenenregler bereit. Fehlende, veränderte oder nicht decodierbare Dateien bleiben sichtbar und lassen sich erneut prüfen. Die Bibliothek lässt sich samt Medien exportieren, abbrechen und auf einem anderen Rechner importieren. Beschreibungen und Medien werden lokal verwaltet.' },
  { id: 'music-transport', title: 'Manuelle Wiedergabe hat Vorrang', text: 'Wähle einen Titel, stelle die Warteschlange zusammen und bediene Pause, Stopp, Weiter, Zurück, Position und Loop. Der kleine Player bleibt beim Wechsel des Arbeitsbereichs sichtbar. Ein manueller Stopp hält auch eingeschaltetes Autoplay an. „Automatik freigeben“ setzt die Auswahl aus der aktuellen fokussierten Gruppe fort. Auswahl und bestätigte Position bleiben gespeichert. Nach erneutem Öffnen bleibt die Ausgabe stumm, bis du ▶ oder einen Titel ausdrücklich startest.' },
  { id: 'music-context', title: 'Musik und Wetter zur Gruppe passen lassen', text: 'Autoplay verwendet Stimmungsregler und Tags der fokussierten Gruppe. Orte, NPCs, Fraktionen und Kreaturprofile können Vibes oder Genres ergänzen oder ersetzen. Die Umgebungsautomatik wählt passende Sounds für Gelände, Wetter und Tageszeit. Ein unlesbarer Wetter- oder Umweltstand ersetzt die letzte gültige Automatik nicht. Füge Sounds ausdrücklich hinzu oder unterdrücke einzelne automatische Sounds; erst die Freigabe beendet diese Vorgabe.' },
];

